/// Truncate to at most `max` bytes, on a char boundary.
/// Byte length <= 512 also implies character count <= 512.
fn truncate_bytes(s: &str, max: usize) -> &str {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
